"""Nội dung trình bày; số liệu lấy từ tập kết quả đã đối chiếu."""
from phase6_contract import FINDING_MESSAGES


def pages(v, vn, pct):
    def n(key, decimals=2):
        return vn(v[key], decimals)

    growth = v["F1_ASEAN_2021"] / v["F1_ASEAN_2000"]
    hydro = v["F2_HYDRO_2021"] / v["F1_ASEAN_2021"]
    modern = v["F2_MODERN_2021"] / v["F1_ASEAN_2021"]
    blue, green, orange = "0072B2", "009E73", "D55E00"
    stats_table = [["Tập quan sát", "Số nước", "Trung bình", "Trung vị", "Độ lệch chuẩn"]]
    for variant, label in [("ALL_OBSERVED", "Toàn bộ quan sát"), ("POSITIVE", "Sản lượng dương"), ("MATERIAL", "Từ 0,05 TWh trở lên")]:
        stats_table.append([label, n(f"F7_SOLAR2021_{variant}_N", 0), n(f"F7_SOLAR2021_{variant}_MEAN", 3), n(f"F7_SOLAR2021_{variant}_MEDIAN", 3), n(f"F7_SOLAR2021_{variant}_SD", 3)])
